--    'Lean', 2),
--(10, STRINGDECODE('- L''organisation veut une approche hybride qui combine plusieurs pratiques.\n- Les \u00e9quipes ont besoin de lignes directrices pour des pratiques d''agilit\u00e9 d''entreprise.\n- Le projet est de grande envergure et n\u00e9cessite une approche adaptable.'),
--     STRINGDECODE('Disciplined Agile Delivery (DAD) est un cadre de gestion de projet agile qui fournit des lignes directrices pour des \u00e9quipes qui \u00e9voluent, combinant des pratiques d''Agile, Lean, et autres approches.\nIl couvre toutes les \u00e9tapes de d\u00e9veloppement, de l''initialisation au d\u00e9ploiement.'),
--     STRINGDECODE('- Les projets sont petits et ne n\u00e9cessitent pas de pratiques agiles d''entreprise.\n- Les \u00e9quipes pr\u00e9f\u00e8rent des cadres plus simples comme Scrum ou Kanban.\n- L''organisation a des contraintes rigides et pr\u00e9f\u00e8re une approche unique.'),
--     'Dad', 2),
--(11, STRINGDECODE('- L''organisation a plusieurs \u00e9quipes de d\u00e9veloppement n\u00e9cessitant une synchronisation.\n- Les projets sont de grande envergure, avec des d\u00e9pendances complexes.\n- L''entreprise souhaite aligner l''agilit\u00e9 de l''\u00e9quipe avec des objectifs d''entreprise plus larges.'),
--     STRINGDECODE('Scaled Agile Framework (SAFe) est un cadre qui permet de mettre \u00e0 l''\u00e9chelle les pratiques agiles pour de grandes entreprises.\nIl fournit une structure pour aligner le d\u00e9veloppement \u00e0 grande \u00e9chelle avec les objectifs strat\u00e9giques de l''entreprise.'),
--     STRINGDECODE('- Les \u00e9quipes ou les projets sont petits et ne n\u00e9cessitent pas de mise \u00e0 l''\u00e9chelle.\n- L''organisation pr\u00e9f\u00e8re des approches moins formelles.'),
--     'Safe', 2),
--(12, STRINGDECODE('- L''organisation utilise d\u00e9j\u00e0 Scrum et souhaite l''\u00e9tendre \u00e0 plusieurs \u00e9quipes.\n- Le projet est complexe et n\u00e9cessite une collaboration inter-\u00e9quipes.\n- L''entreprise souhaite minimiser la bureaucratie tout en mettant \u00e0 l''\u00e9chelle.'),
--     STRINGDECODE('Large-Scale Scrum (LeSS) est une extension de Scrum pour les grandes \u00e9quipes de d\u00e9veloppement.\nIl conserve les principes de base de Scrum tout en les adaptant \u00e0 une \u00e9chelle plus grande, avec plusieurs \u00e9quipes travaillant sur le m\u00eame produit.'),
--     STRINGDECODE('- Les \u00e9quipes n''ont pas d''exp\u00e9rience avec Scrum.\n- L''organisation a des exigences rigides de processus et de documentation.\n- Les projets ne sont pas assez grands pour justifier la mise \u00e0 l''\u00e9chelle.'),
--     'Less', 2),
--(13, STRINGDECODE('- Les \u00e9quipes Scrum doivent collaborer sur des produits complexes.\n- L''accent est mis sur l''int\u00e9gration continue et la gestion des d\u00e9pendances.\n- L''organisation veut utiliser un cadre qui reste proche des principes de Scrum.'),
--     STRINGDECODE('Nexus est un cadre de mise \u00e0 l''\u00e9chelle de Scrum con\u00e7u pour des \u00e9quipes qui travaillent ensemble sur un produit unique.\nIl se concentre sur la gestion des d\u00e9pendances et l''int\u00e9gration continue.'),
--     STRINGDECODE('- Les \u00e9quipes ne sont pas familiaris\u00e9es avec Scrum.\n- Le projet est simple et n''a pas besoin de mise \u00e0 l''\u00e9chelle.\n- Les \u00e9quipes pr\u00e9f\u00e8rent des approches plus l\u00e9g\u00e8res comme LeSS.'),
--     'Nexus', 2),
--(14, STRINGDECODE('- Plusieurs \u00e9quipes Scrum doivent travailler en parall\u00e8le et coordonner leurs efforts.\n- L''objectif est de g\u00e9rer les interd\u00e9pendances tout en utilisant les principes Scrum.'),
--     STRINGDECODE('Scrum of Scrums est une technique de coordination utilis\u00e9e pour mettre \u00e0 l''\u00e9chelle Scrum dans les grandes organisations.\nDes repr\u00e9sentants de chaque \u00e9quipe Scrum se rencontrent r\u00e9guli\u00e8rement pour coordonner le travail.'),
--     STRINGDECODE('- Les \u00e9quipes ne sont pas autonomes ou ne ma\u00eetrisent pas bien Scrum.\n- Le projet est petit ou n''implique qu''une seule \u00e9quipe.\n- Il n''y a pas de besoins de coordination fr\u00e9quente.'),
--     'Scrum of Scrums', 2),
--(15, STRINGDECODE('- L''organisation veut encourager une culture d''autonomie et d''innovation.\n- L''accent est mis sur la flexibilit\u00e9 organisationnelle et la collaboration.\n- Les \u00e9quipes pr\u00e9f\u00e8rent travailler de mani\u00e8re autonome tout en maintenant une synchronisation.'),
--     STRINGDECODE('Le mod\u00e8le Spotify est une approche de gestion d''\u00e9quipe agile, mettant l''accent sur la culture et la structure d''\u00e9quipe autonome.\nIl vise \u00e0 maximiser l''alignement et l''autonomie.'),
--     STRINGDECODE('- L''organisation n\u00e9cessite des contr\u00f4les stricts et une hi\u00e9rarchie rigide.\n- Les \u00e9quipes n''ont pas l''exp\u00e9rience n\u00e9cessaire pour g\u00e9rer leur autonomie.\n- Les projets ont des exigences formelles de documentation et de processus.'),
--     'Spotify', 2),
--(16, STRINGDECODE('- L''organisation veut appliquer des principes agiles au niveau de l''entreprise, pas seulement au d\u00e9veloppement.\n- Les \u00e9quipes veulent un cadre flexible mais structur\u00e9 pour diff\u00e9rents d\u00e9partements.\n- L''objectif est d''aligner l''ensemble de l''organisation avec une culture agile.'),
--     STRINGDECODE('Enterprise Scrum est une m\u00e9thode d''\u00e9chelle agile qui permet l''application de Scrum dans divers contextes organisationnels (marketing, vente, etc.), pas seulement pour le d\u00e9veloppement logiciel.'),
--     STRINGDECODE('- L''entreprise n''a pas de culture d''innovation ou de flexibilit\u00e9.\n- Les \u00e9quipes ne ma\u00eetrisent pas les concepts de base de Scrum.\n- Les projets sont d\u00e9j\u00e0 bien g\u00e9r\u00e9s avec d''autres cadres d''agilit\u00e9 \u00e0 l''\u00e9chelle.'),
--     'Enterprise Scrum (ES)', 2)
